/// <summary>
/// Logic block containing business logic for adding a count line
/// </summary>
class MwmsLogicBlockAddCountLine extends MwmsLogicBlockCreateCountingJournalLine//MwmsLogicBlockJournalLinesCommon implements TFMLogicBlockDataCollectionInterface, TFMLogicBlockPrePostDataModifyInterface
{
    InventTable             inventTable;

}

Method.Source:
public static MwmsLogicBlockAddCountLine Construct()
{
    return new MwmsLogicBlockAddCountLine();
}

public TFMRegistrationCollectors registrationCollectors()
{
    TFMRegistrationCollectors regCols = components.getCollectors();

    regCols.removeCollector(TFMConstants::Quantity());
    return regCols;
}

public TFMReferenceDataConfiguration headerFieldsNeeded()
{
    refConf = components.getHeaders();        
    return refConf;
}

/// <summary>
/// Name of the block Type.
/// </summary>
/// <returns>Name of the block</returns>
public Name blockName()
{
    return "@MobileWMS:AddCountLine";
}

/// <summary>
/// Method to set up tables to be used in the posting. Ensures that addons can be made, that can modify the data of the block before posting, when needed.
/// </summary>
public void preparePost()
{
    this.getTables();
}

public TFMPostResponseData post()
{
    TFMPostResponseData                 response = TFMPostResponseData::Construct();
    inventJournalTrans.inventMovement();
    inventJournalTrans.Counted      = 0;
    inventJournalTrans.Qty          = 0;
    inventJournalTrans.InventOnHand = InventSumDatePhysicalDim::onHandQty(MobHelper::today(),inventJournalTrans.ItemId,InventDim::find(inventJournalTrans.InventDimId),InventDimParm::activeDimFlag(InventDimGroupSetup::newInventTable(request.parmInventTable())));
    inventJournalTrans.inventMovement().journalSetCounted();
    inventJournalTrans.MobRegisteredOnMobile = false;
    inventJournalTrans.write();
    inventJournalTable::initTotal(inventJournalTable);
    inventJournalTable.write();
    response.parmResponseText("@SYS80122");

    return response;
}
